CREATE TABLE public.companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, enterprise_number text, simpla_bound boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.companies TO authenticated; GRANT ALL ON public.companies TO service_role;
ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_company_owner ON public.companies FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX companies_one_simpla_per_user ON public.companies(user_id) WHERE simpla_bound;
CREATE FUNCTION public.owns_company(_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.companies WHERE id=_company AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.owns_company(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owns_company(uuid) TO authenticated;
CREATE TABLE public.fin_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,month date NOT NULL,kind text NOT NULL CHECK(kind IN('omzet','kost','kas')),category text NOT NULL DEFAULT 'algemeen',account text,amount numeric NOT NULL,level text NOT NULL DEFAULT 'detail' CHECK(level IN('detail','totaal')),description text,source text NOT NULL DEFAULT 'handmatig',source_ref text,dedupe_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,dedupe_key),CHECK(extract(day from month)=1));
CREATE TABLE public.fin_months(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,month date NOT NULL,revenue_complete boolean NOT NULL DEFAULT false,costs_complete boolean NOT NULL DEFAULT false,bank_complete boolean NOT NULL DEFAULT false,note text,UNIQUE(company_id,month),CHECK(extract(day from month)=1));
CREATE TABLE public.fin_budgets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,month date NOT NULL,category text NOT NULL,amount numeric NOT NULL CHECK(amount>=0),UNIQUE(company_id,month,category),CHECK(extract(day from month)=1));
CREATE TABLE public.fin_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,direction text NOT NULL CHECK(direction IN('aankoop','verkoop')),doc_type text NOT NULL DEFAULT 'factuur' CHECK(doc_type IN('factuur','creditnota')),original_invoice_id uuid REFERENCES public.fin_invoices(id) ON DELETE SET NULL,counterparty text,number text,invoice_date date,due_date date,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','betaald','betwist')),review_status text NOT NULL DEFAULT 'te_beoordelen' CHECK(review_status IN('te_beoordelen','goedgekeurd')),bank_ref text,paid_at date,source text NOT NULL DEFAULT 'handmatig',source_ref text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,source,source_ref));
CREATE FUNCTION public.owns_fin_invoice(_inv uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.fin_invoices WHERE id=_inv AND user_id=auth.uid() AND public.owns_company(company_id)) $$;
REVOKE ALL ON FUNCTION public.owns_fin_invoice(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owns_fin_invoice(uuid) TO authenticated;
CREATE TABLE public.fin_invoice_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid,invoice_id uuid NOT NULL REFERENCES public.fin_invoices(id) ON DELETE CASCADE,description text,ex_vat numeric NOT NULL DEFAULT 0 CHECK(ex_vat>=0),vat numeric NOT NULL DEFAULT 0 CHECK(vat>=0),account text,category text,is_investment boolean NOT NULL DEFAULT false,suggestion_rule_id uuid,confidence numeric CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1));
CREATE TABLE public.fin_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,supplier_key text NOT NULL,keyword text NOT NULL DEFAULT '',account text NOT NULL,category text NOT NULL,scope text NOT NULL DEFAULT 'soortgelijk' CHECK(scope IN('soortgelijk','leverancier')),hits integer NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,supplier_key,keyword));
CREATE TABLE public.fin_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid,entity text NOT NULL,entity_id uuid,action text NOT NULL,detail jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.fin_investments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,name text NOT NULL,purchase_amount numeric,capitalizable_amount numeric,start_date date,useful_life_months integer,residual_value numeric NOT NULL DEFAULT 0,opening_accumulated numeric NOT NULL DEFAULT 0,opening_cutoff date,method text NOT NULL DEFAULT 'lineair' CHECK(method='lineair'),is_land boolean NOT NULL DEFAULT false,disposal_date date,invoice_line_id uuid REFERENCES public.fin_invoice_lines(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(useful_life_months IS NULL OR useful_life_months>0),CHECK((purchase_amount IS NULL OR purchase_amount>=0) AND (capitalizable_amount IS NULL OR capitalizable_amount>=0)),CHECK(residual_value>=0 AND residual_value<=coalesce(capitalizable_amount,purchase_amount,residual_value)),CHECK(opening_accumulated>=0 AND opening_accumulated<=coalesce(capitalizable_amount,purchase_amount,opening_accumulated+residual_value)-residual_value),CHECK(opening_accumulated=0 OR opening_cutoff IS NOT NULL),CHECK((opening_cutoff IS NULL OR start_date IS NULL OR opening_cutoff>=start_date) AND (disposal_date IS NULL OR start_date IS NULL OR disposal_date>=start_date)));
CREATE UNIQUE INDEX fin_investments_invoice_line_unique ON public.fin_investments(invoice_line_id) WHERE invoice_line_id IS NOT NULL;
CREATE TABLE public.fin_loans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,name text NOT NULL,principal numeric NOT NULL,annual_rate numeric NOT NULL,months integer NOT NULL,start_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(principal>0 AND months BETWEEN 1 AND 600 AND annual_rate>=0 AND annual_rate<100));
CREATE TABLE public.fin_competitors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),name text NOT NULL,enterprise_number text,identity_confirmed boolean NOT NULL DEFAULT false,is_own boolean NOT NULL DEFAULT false,note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION public.owns_competitor(_c uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.fin_competitors WHERE id=_c AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.owns_competitor(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owns_competitor(uuid) TO authenticated;
CREATE TABLE public.fin_competitor_metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),competitor_id uuid NOT NULL REFERENCES public.fin_competitors(id) ON DELETE CASCADE,fiscal_year integer NOT NULL CHECK(fiscal_year BETWEEN 1990 AND 2100),scope text NOT NULL DEFAULT 'enkelvoudig',revenue numeric,gross_margin numeric,profit numeric,equity numeric,employees numeric,source text NOT NULL,retrieved_at date NOT NULL,UNIQUE(competitor_id,fiscal_year,scope));
CREATE TABLE public.fin_sync_status(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,source text NOT NULL,last_success_at timestamptz,last_error text,last_error_at timestamptz,UNIQUE(company_id,source));
CREATE TABLE public.fin_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,number text NOT NULL CHECK(number ~ '^[0-9]{1,10}$'),name text NOT NULL CHECK(length(trim(name))>0),source text NOT NULL DEFAULT 'handmatig',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,number));
CREATE TABLE public.fin_journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,journal text NOT NULL CHECK(journal IN('aankoop','verkoop','bank','divers','opening')),entry_date date NOT NULL,description text,reference text,source text NOT NULL,source_ref text,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX fin_journal_entries_source ON public.fin_journal_entries(company_id,source,source_ref) WHERE source_ref IS NOT NULL;
CREATE TABLE public.fin_journal_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,entry_id uuid NOT NULL REFERENCES public.fin_journal_entries(id) ON DELETE CASCADE,account text NOT NULL,debit numeric NOT NULL DEFAULT 0 CHECK(debit>=0),credit numeric NOT NULL DEFAULT 0 CHECK(credit>=0),vat_grid text,description text);
CREATE INDEX fin_journal_lines_entry ON public.fin_journal_lines(entry_id); CREATE INDEX fin_journal_lines_company ON public.fin_journal_lines(company_id,account);
CREATE TABLE public.fin_bank_tx(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,tx_date date NOT NULL,amount numeric NOT NULL,counterparty text,description text,bank_account text,dedupe_key text NOT NULL,matched_invoice_id uuid REFERENCES public.fin_invoices(id) ON DELETE SET NULL,entry_id uuid REFERENCES public.fin_journal_entries(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,dedupe_key));
CREATE TABLE public.fin_recurring(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,description text NOT NULL,amount numeric NOT NULL CHECK(amount>0),debit_account text NOT NULL,credit_account text NOT NULL,journal text NOT NULL DEFAULT 'divers',start_month date NOT NULL,end_month date,day_of_month integer NOT NULL DEFAULT 1 CHECK(day_of_month BETWEEN 1 AND 28),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.fin_loan_schedule(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,loan_key text NOT NULL,loan_name text NOT NULL,reference text,kind text NOT NULL CHECK(kind IN('aflossing','herklassering')),due_date date NOT NULL,capital numeric NOT NULL DEFAULT 0 CHECK(capital>=0),interest numeric NOT NULL DEFAULT 0 CHECK(interest>=0),debit_account text NOT NULL,credit_account text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,loan_key,kind,due_date));
CREATE TABLE public.fin_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),finance_company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,finance_event_key text NOT NULL,title text NOT NULL,body_text text,priority text NOT NULL DEFAULT 'normaal',due_date date,status text NOT NULL DEFAULT 'taak' CHECK(status IN('taak','opvolgen','afgerond','genegeerd')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,finance_company_id,finance_event_key));
CREATE TABLE public.fin_supplier_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid(),simpla_id text NOT NULL,supplier_name text,bill_number text,bill_date date,total_ex_vat numeric NOT NULL DEFAULT 0,total_inc_vat numeric NOT NULL DEFAULT 0,UNIQUE(user_id,simpla_id));
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['fin_entries','fin_months','fin_budgets','fin_invoices','fin_rules','fin_investments','fin_loans','fin_sync_status','fin_accounts','fin_bank_tx','fin_recurring','fin_loan_schedule'] LOOP
EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY finance_owner ON public.%I FOR ALL TO authenticated USING(user_id=auth.uid() AND public.owns_company(company_id)) WITH CHECK(user_id=auth.uid() AND public.owns_company(company_id))',t); END LOOP;
FOREACH t IN ARRAY ARRAY['fin_invoice_lines','fin_audit','fin_competitors','fin_competitor_metrics','fin_journal_entries','fin_journal_lines','fin_tasks','fin_supplier_imports'] LOOP EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fin_invoice_lines,public.fin_competitors,public.fin_competitor_metrics,public.fin_tasks TO authenticated; GRANT SELECT,INSERT ON public.fin_audit,public.fin_supplier_imports TO authenticated; GRANT SELECT,DELETE ON public.fin_journal_entries TO authenticated; GRANT SELECT ON public.fin_journal_lines TO authenticated;
CREATE POLICY finance_lines_owner ON public.fin_invoice_lines FOR ALL TO authenticated USING(user_id=auth.uid() AND public.owns_fin_invoice(invoice_id)) WITH CHECK(user_id=auth.uid() AND public.owns_fin_invoice(invoice_id));
CREATE POLICY finance_audit_read ON public.fin_audit FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')); CREATE POLICY finance_audit_insert ON public.fin_audit FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'admin') AND (company_id IS NULL OR public.owns_company(company_id)));
CREATE POLICY finance_competitors_owner ON public.fin_competitors FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE POLICY finance_metrics_owner ON public.fin_competitor_metrics FOR ALL TO authenticated USING(user_id=auth.uid() AND public.owns_competitor(competitor_id)) WITH CHECK(user_id=auth.uid() AND public.owns_competitor(competitor_id));
CREATE POLICY finance_journal_read ON public.fin_journal_entries FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.owns_company(company_id)); CREATE POLICY finance_journal_delete ON public.fin_journal_entries FOR DELETE TO authenticated USING(user_id=auth.uid() AND public.owns_company(company_id));
CREATE POLICY finance_posted_read ON public.fin_journal_lines FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.owns_company(company_id));
CREATE POLICY finance_tasks_owner ON public.fin_tasks FOR ALL TO authenticated USING(user_id=auth.uid() AND public.owns_company(finance_company_id)) WITH CHECK(user_id=auth.uid() AND public.owns_company(finance_company_id));
CREATE POLICY finance_supplier_read ON public.fin_supplier_imports FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'admin')); CREATE POLICY finance_supplier_insert ON public.fin_supplier_imports FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.fin_validate_invoice() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.original_invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fin_invoices WHERE id=NEW.original_invoice_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Oorspronkelijke factuur hoort niet bij dit bedrijf'; END IF; IF NEW.due_date IS NOT NULL AND NEW.invoice_date IS NOT NULL AND NEW.due_date<NEW.invoice_date THEN RAISE EXCEPTION 'Vervaldatum ligt voor factuurdatum'; END IF; RETURN NEW; END $$;
CREATE TRIGGER fin_invoices_validate BEFORE INSERT OR UPDATE ON public.fin_invoices FOR EACH ROW EXECUTE FUNCTION public.fin_validate_invoice();
CREATE FUNCTION public.fin_post_entry(_company uuid,_journal text,_date date,_description text,_reference text,_source text,_source_ref text,_lines jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; _d numeric:=0; _c numeric:=0; l jsonb; _uid uuid:=auth.uid(); BEGIN IF _uid IS NULL OR NOT public.owns_company(_company) THEN RAISE EXCEPTION 'Geen toegang tot dit bedrijf'; END IF; IF jsonb_typeof(_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(_lines)<2 THEN RAISE EXCEPTION 'Een boeking heeft minstens twee lijnen nodig'; END IF; FOR l IN SELECT * FROM jsonb_array_elements(_lines) LOOP IF coalesce((l->>'debit')::numeric,0)<0 OR coalesce((l->>'credit')::numeric,0)<0 THEN RAISE EXCEPTION 'Negatieve bedragen niet toegelaten'; END IF; IF NOT EXISTS(SELECT 1 FROM public.fin_accounts WHERE company_id=_company AND number=l->>'account') THEN RAISE EXCEPTION 'Rekening % bestaat niet in het rekeningschema',l->>'account'; END IF; _d:=_d+coalesce((l->>'debit')::numeric,0); _c:=_c+coalesce((l->>'credit')::numeric,0); END LOOP; IF round(_d,2)<>round(_c,2) OR _d=0 THEN RAISE EXCEPTION 'Boeking niet in evenwicht'; END IF;
INSERT INTO public.fin_journal_entries(user_id,company_id,journal,entry_date,description,reference,source,source_ref) VALUES(_uid,_company,_journal,_date,_description,_reference,_source,_source_ref) RETURNING id INTO _id;
INSERT INTO public.fin_journal_lines(user_id,company_id,entry_id,account,debit,credit,vat_grid,description) SELECT _uid,_company,_id,x->>'account',round(coalesce((x->>'debit')::numeric,0),2),round(coalesce((x->>'credit')::numeric,0),2),nullif(x->>'vat_grid',''),x->>'description' FROM jsonb_array_elements(_lines) x;
INSERT INTO public.fin_audit(user_id,company_id,entity,entity_id,action,detail) VALUES(_uid,_company,'boeking',_id,'geboekt',jsonb_build_object('dagboek',_journal,'bron',_source,'bedrag',round(_d,2))); RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.fin_post_entry(uuid,text,date,text,text,text,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.fin_post_entry(uuid,text,date,text,text,text,text,jsonb) TO authenticated;
CREATE FUNCTION public.fin_validate_links() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='fin_bank_tx' THEN IF NEW.matched_invoice_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fin_invoices WHERE id=NEW.matched_invoice_id AND company_id=NEW.company_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Factuur hoort niet bij dit bedrijf'; END IF; IF NEW.entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fin_journal_entries WHERE id=NEW.entry_id AND company_id=NEW.company_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Boeking hoort niet bij dit bedrijf'; END IF; ELSIF TG_TABLE_NAME='fin_investments' AND NEW.invoice_line_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.fin_invoice_lines l JOIN public.fin_invoices i ON i.id=l.invoice_id WHERE l.id=NEW.invoice_line_id AND i.company_id=NEW.company_id AND i.user_id=NEW.user_id) THEN RAISE EXCEPTION 'Investering hoort niet bij deze factuur'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER fin_bank_links BEFORE INSERT OR UPDATE ON public.fin_bank_tx FOR EACH ROW EXECUTE FUNCTION public.fin_validate_links(); CREATE TRIGGER fin_investment_links BEFORE INSERT OR UPDATE ON public.fin_investments FOR EACH ROW EXECUTE FUNCTION public.fin_validate_links();